<?php
namespace Modules\BankingMicrofinanceTreasury\Http\Controllers;use Illuminate\Http\Request;use Illuminate\Routing\Controller;use Modules\BankingMicrofinanceTreasury\Entities\TreasuryFundingLine;
class FundingLineController extends Controller{public function index(){return view('bankingmicrofinancetreasury::funding_lines.index',['lines'=>TreasuryFundingLine::latest()->paginate(25)]);}public function create(){return view('bankingmicrofinancetreasury::funding_lines.form',['line'=>new TreasuryFundingLine]);}public function store(Request $r){$data=$r->all()+['business_id'=>auth()->user()->business_id ?? null];$data['available_limit']=($data['approved_limit']??0)-($data['drawn_amount']??0);TreasuryFundingLine::create($data);return redirect()->route('bkg.mfi.treasury.funding-lines.index')->with('status','Funding line saved');}public function edit(TreasuryFundingLine $fundingLine){return view('bankingmicrofinancetreasury::funding_lines.form',['line'=>$fundingLine]);}public function update(Request $r,TreasuryFundingLine $fundingLine){$data=$r->all();$data['available_limit']=($data['approved_limit']??$fundingLine->approved_limit)-($data['drawn_amount']??$fundingLine->drawn_amount);$fundingLine->update($data);return redirect()->route('bkg.mfi.treasury.funding-lines.index')->with('status','Funding line updated');}public function destroy(TreasuryFundingLine $fundingLine){$fundingLine->delete();return back();}}
